/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Mul, Pow, Sym, abs, add, compogen, decompogen, fn, mul, pow, rational, rel, symbols } from '../../src';
import { at, sympyStr } from '../sympy-str';

describe("doctests of sympy.solvers.decompogen", () => {
  it("compogen([sin(x), cos(x)], x)", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([fn('sin', [x]), fn('cos', [x])], x))).toBe('sin(cos(x))');
  });
  it("compogen([x**2 + x + 1, sin(x)], x)", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([add(1, x, pow(x, 2)), fn('sin', [x])], x))).toBe('sin(x)**2 + sin(x) + 1');
  });
  it("compogen([sqrt(x), 6*x**2 - 5], x)", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([pow(x, rational(1, 2)), add(-5, mul(6, pow(x, 2)))], x))).toBe('sqrt(6*x**2 - 5)');
  });
  it("compogen([sin(x), sqrt(x), cos(x), x**2 + 1], x)", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([fn('sin', [x]), pow(x, rational(1, 2)), fn('cos', [x]), add(1, pow(x, 2))], x))).toBe('sin(sqrt(cos(x**2 + 1)))');
  });
  it("compogen([x**2 - x - 1, x**2 + x], x)", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([add(-1, pow(x, 2), mul(-1, x)), add(x, pow(x, 2))], x))).toBe('-x**2 - x + (x**2 + x)**2 - 1');
  });
  it("decompogen(sin(cos(x)), x)", () => {
    const x = new Sym('x');
    const v1 = fn('cos', [x]);
    expect(sympyStr([at(decompogen(fn('sin', [v1]), x), 0), v1])).toBe('[sin(x), cos(x)]');
  });
  it("decompogen(sin(x)**2 + sin(x) + 1, x)", () => {
    const x = new Sym('x');
    const v1 = fn('sin', [x]);
    expect(sympyStr([at(decompogen(add(1, pow(fn('sin', [x]), 2), v1), x), 0), v1])).toBe('[x**2 + x + 1, sin(x)]');
  });
  it("decompogen(sqrt(6*x**2 - 5), x)", () => {
    const x = new Sym('x');
    const v1 = decompogen(pow(add(-5, mul(6, pow(x, 2))), rational(1, 2)), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[sqrt(x), 6*x**2 - 5]');
  });
  it("decompogen(sin(sqrt(cos(x**2 + 1))), x)", () => {
    const x = new Sym('x');
    const v1 = decompogen(fn('sin', [pow(fn('cos', [add(1, pow(x, 2))]), rational(1, 2))]), x);
    expect(sympyStr([at(v1, 0), at(v1, 1), at(v1, 2), at(v1, 3)])).toBe('[sin(x), sqrt(x), cos(x), x**2 + 1]');
  });
  it("decompogen(x**4 + 2*x**3 - x - 1, x)", () => {
    const x = new Sym('x');
    const v1 = decompogen(add(-1, pow(x, 4), mul(-1, x), mul(2, pow(x, 3))), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[x**2 - x - 1, x**2 + x]');
  });
});

describe("sympy/solvers/tests/test_decompogen.py", () => {
  it("test_decompogen:13", () => {
    const x = new Sym('x');
    const v1 = fn('cos', [x]);
    expect(sympyStr([at(decompogen(fn('sin', [v1]), x), 0), v1])).toBe('[sin(x), cos(x)]');
  });
  it("test_decompogen:14", () => {
    const x = new Sym('x');
    const v1 = fn('sin', [x]);
    expect(sympyStr([at(decompogen(new Add([rational(1), new Pow(fn('sin', [x]), rational(2)), v1]), x), 0), v1])).toBe('[x**2 + x + 1, sin(x)]');
  });
  it("test_decompogen:15", () => {
    const x = new Sym('x');
    const v1 = decompogen(new Pow(new Add([rational(-5), new Mul([rational(6), new Pow(x, rational(2))])]), rational(1, 2)), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[sqrt(x), 6*x**2 - 5]');
  });
  it("test_decompogen:16", () => {
    const x = new Sym('x');
    const v1 = decompogen(fn('sin', [new Pow(fn('cos', [new Add([rational(1), new Pow(x, rational(2))])]), rational(1, 2))]), x);
    expect(sympyStr([at(v1, 0), at(v1, 1), at(v1, 2), at(v1, 3)])).toBe('[sin(x), sqrt(x), cos(x), x**2 + 1]');
  });
  it("test_decompogen:17", () => {
    const x = new Sym('x');
    const v1 = fn('cos', [x]);
    const v2 = decompogen(abs(new Add([rational(-4), new Pow(fn('cos', [x]), rational(2)), new Mul([rational(3), v1])])), x);
    expect(sympyStr([at(v2, 0), at(v2, 1), v1])).toBe('[Abs(x), x**2 + 3*x - 4, cos(x)]');
  });
  it("test_decompogen:18", () => {
    const x = new Sym('x');
    const v1 = fn('sin', [x]);
    expect(sympyStr([at(decompogen(new Add([new Pow(fn('sin', [x]), rational(2)), new Mul([rational(-1, 2), new Pow(rational(3), rational(1, 2))]), v1]), x), 0), v1])).toBe('[x**2 + x - sqrt(3)/2, sin(x)]');
  });
  it("test_decompogen:19", () => {
    const [y, x] = symbols('y x');
    const v1 = fn('cos', [x]);
    const v2 = decompogen(abs(new Add([rational(-4), new Pow(fn('cos', [y]), rational(2)), new Mul([rational(3), v1])])), x);
    expect(sympyStr([at(v2, 0), at(v2, 1), v1])).toBe('[Abs(x), 3*x + cos(y)**2 - 4, cos(x)]');
  });
  it("test_decompogen:20", () => {
    const x = new Sym('x');
    expect(sympyStr([x])).toBe('[x]');
  });
  it("test_decompogen:21", () => {
    expect(sympyStr([rational(1)])).toBe('[1]');
  });
  it("test_decompogen:22", () => {
    const x = new Sym('x');
    expect(sympyStr([fn('Max', [rational(3), x])])).toBe('[Max(3, x)]');
  });
  it("test_decompogen:23", () => {
    const x = new Sym('x');
    expect(() => decompogen(rel('Lt', x, 5), x)).toThrow(TypeError);
  });
  it("test_decompogen:25", () => {
    const x = new Sym('x');
    const v1 = decompogen(fn('Max', [new Pow(new Add([rational(3), new Mul([rational(2), x])]), rational(1, 2)), new Pow(new Add([rational(3), new Mul([rational(2), x])]), rational(2))]), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[Max(sqrt(x), x**2), 2*x + 3]');
  });
  it("test_decompogen:26", () => {
    const [y, x] = symbols('y x');
    const v1 = decompogen(fn('Max', [y, new Add([rational(3), new Mul([rational(2), x])]), new Pow(new Add([rational(3), new Mul([rational(2), x])]), rational(2))]), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[Max(x, x**2, y), 2*x + 3]');
  });
  it("test_decompogen:27", () => {
    const x = new Sym('x');
    expect(sympyStr([fn('Max', [fn('sin', [x]), new Add([rational(3), new Mul([rational(2), x])])])])).toBe('[Max(2*x + 3, sin(x))]');
  });
  it("test_decompogen_poly:31", () => {
    const x = new Sym('x');
    const v1 = decompogen(new Add([rational(1), new Pow(x, rational(4)), new Mul([rational(2), new Pow(x, rational(2))])]), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[x**2 + 2*x + 1, x**2]');
  });
  it("test_decompogen_poly:32", () => {
    const x = new Sym('x');
    const v1 = decompogen(new Add([rational(-1), new Pow(x, rational(4)), new Mul([rational(-1), x]), new Mul([rational(2), new Pow(x, rational(3))])]), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[x**2 - x - 1, x**2 + x]');
  });
  it("test_compogen:46", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([fn('sin', [x]), fn('cos', [x])], x))).toBe('sin(cos(x))');
  });
  it("test_compogen:47", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([new Add([rational(1), x, new Pow(x, rational(2))]), fn('sin', [x])], x))).toBe('sin(x)**2 + sin(x) + 1');
  });
  it("test_compogen:48", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([new Pow(x, rational(1, 2)), new Add([rational(-5), new Mul([rational(6), new Pow(x, rational(2))])])], x))).toBe('sqrt(6*x**2 - 5)');
  });
  it("test_compogen:49", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([fn('sin', [x]), new Pow(x, rational(1, 2)), fn('cos', [x]), new Add([rational(1), new Pow(x, rational(2))])], x))).toBe('sin(sqrt(cos(x**2 + 1)))');
  });
  it("test_compogen:51", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([abs(x), new Add([rational(-4), new Pow(x, rational(2)), new Mul([rational(3), x])]), fn('cos', [x])], x))).toBe('Abs(cos(x)**2 + 3*cos(x) - 4)');
  });
  it("test_compogen:53", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([new Add([x, new Pow(x, rational(2)), new Mul([rational(-1, 2), new Pow(rational(3), rational(1, 2))])]), fn('sin', [x])], x))).toBe('sin(x)**2 + sin(x) - sqrt(3)/2');
  });
  it("test_compogen:55", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(compogen([abs(x), new Add([rational(-4), new Pow(fn('cos', [y]), rational(2)), new Mul([rational(3), x])]), fn('cos', [x])], x))).toBe('Abs(3*cos(x) + cos(y)**2 - 4)');
  });
  it("test_compogen:57", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([new Add([rational(1), new Pow(x, rational(2)), new Mul([rational(2), x])]), new Pow(x, rational(2))], x))).toBe('x**4 + 2*x**2 + 1');
  });
  it("test_compogen:59", () => {
    const x = new Sym('x');
    expect(sympyStr(compogen([new Add([rational(-1), new Pow(x, rational(2)), new Mul([rational(-1), x])]), new Add([x, new Pow(x, rational(2))])], x))).toBe('-x**2 - x + (x**2 + x)**2 - 1');
  });
});
